      } else if (method === 'median') {
        const mid = Math.floor(b.items.length / 2);
        const med = b.items.length % 2 !== 0 ? b.items[mid] : (b.items[mid-1] + b.items[mid]) / 2;
        smoothed = b.items.map(() => med.toFixed(1));
      } else if (method === 'boundary') {
        const minVal = b.items[0];
        const maxVal = b.items[b.items.length - 1];
        smoothed = b.items.map(val => (Math.abs(val - minVal) < Math.abs(val - maxVal)) ? minVal : maxVal);
