      html += `
        <tr style="border-bottom: 1px solid #e1e4e8;">
          <td style="padding: 4px; font-weight: bold; color: #8250df;">${b.label}</td>
          <td style="padding: 4px; color: #24292f;">${b.items.join(', ')}</td>
